import{_ as o,o as n,c as a,ag as s,j as r}from"./chunks/framework.KxDd3USm.js";const b=JSON.parse('{"title":"04.4 UML 行为图与交互图 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"04-面向对象与设计模式/04-UML行为与交互图.md","filePath":"04-面向对象与设计模式/04-UML行为与交互图.md"}'),e={name:"04-面向对象与设计模式/04-UML行为与交互图.md"},d={class:"fig"},g={"data-figure-id":"figure-22",viewBox:"0 0 760 365",width:"100%",style:{"max-width":"760px"},role:"img","aria-label":"订单处理活动图，分为顾客和系统两个泳道。顾客提交订单后，系统校验订单；校验通过时，系统分叉并发执行生成发票和安排配送，二者汇合后发送确认；校验不通过时发送拒绝提示。图中菱形是二选一的分支，粗横线是两项都执行的分叉与汇合。"},l={class:"fig"},p={"data-figure-id":"figure-23",viewBox:"0 0 760 265",width:"100%",style:{"max-width":"760px"},role:"img","aria-label":"订单状态图。初态进入待支付；支付成功且库存充足时转到待发货，动作是扣库存；支付超时转到已取消，动作是释放库存；待发货经发货事件转到运输中，再经签收事件转到已完成终态。每条转移均标明事件、可选监护条件和动作。"};function c(i,t,h,u,x,_){return n(),a("div",null,[t[4]||(t[4]=s(`<h1 id="_04-4-uml-行为图与交互图-★★★" tabindex="-1">04.4 UML 行为图与交互图 ★★★ <a class="header-anchor" href="#_04-4-uml-行为图与交互图-★★★" aria-label="Permalink to &quot;04.4 UML 行为图与交互图 ★★★&quot;">​</a></h1><p><strong>顺序图要素</strong>（从图上一眼能指出来）：<strong>对象</strong>（顶部方框）、<strong>生命线</strong>（对象下方的竖直虚线）、<strong>激活/控制焦点</strong>（生命线上叠的窄长条，表示对象正在执行）、<strong>消息</strong>（水平箭头）、<strong>返回消息</strong>（<strong>虚线</strong>箭头，表示把结果交回）。</p><p><strong>消息方向与种类</strong>：</p><table tabindex="0"><thead><tr><th>消息</th><th>画法</th><th>含义</th></tr></thead><tbody><tr><td>同步消息</td><td><strong>实线 + 实心箭头</strong></td><td>发送者<strong>等</strong>对方处理完（普通方法调用）</td></tr><tr><td>异步消息</td><td>实线 + 空心箭头</td><td>发送者<strong>不等</strong>（发完就走）</td></tr><tr><td>返回消息</td><td><strong>虚线 + 箭头</strong></td><td>把结果回传给调用者</td></tr></tbody></table><p><strong>一条最重要的判图规律</strong>：<strong>从左边第一个对象开始，箭头指向谁，就是谁在干活</strong>；消息自左向右排序，<strong>上下位置 = 时间先后</strong>——所以案例题让你&quot;按说明填消息&quot;，就是<strong>照典型事件流的步骤顺序往右下方排</strong>。</p><p><strong>通信图（协作图）</strong>：同样的交互内容，但<strong>画法完全不同</strong>——对象是<strong>网络式</strong>散布的，消息写在<strong>对象之间的连线上</strong>并用<strong>序号</strong>标注调用层次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        :Patron</span></span>
<span class="line"><span>           │  2: isFaculty()</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span> 1: checkOut(bookID)      :CheckoutSessionController</span></span>
<span class="line"><span>           │  3: find(bookID)</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>        :Book  ──── 4: recordBookLoan() ───▶ :Catalog</span></span></code></pre></div><p>序号里的点表示<strong>嵌套层级</strong>（<code>1.1</code> 是 <code>1</code> 内部调用的第一句，<code>1.1.2</code> 再深一层）。<strong>顺序图 vs 通信图对照</strong>：两者<strong>语义等价、可以互相转换</strong>；顺序图突出<strong>时间顺序</strong>，通信图突出<strong>对象间的链接结构与调用层次</strong>。</p><p><strong>反例演示（易错）</strong>：判断&quot;哪张是顺序图&quot;不要只看有没有箭头——<strong>定音锤是&quot;有没有生命线（竖直虚线）&quot;</strong>：有竖直生命线、消息横着排的是顺序图；对象用连线连成网状、序号写在线上的是通信图。</p><h3 id="_3-4-活动图-流程-并发-泳道" tabindex="-1">3.4 活动图：流程 + 并发 + 泳道 <a class="header-anchor" href="#_3-4-活动图-流程-并发-泳道" aria-label="Permalink to &quot;3.4 活动图：流程 + 并发 + 泳道&quot;">​</a></h3><p><strong>要素</strong>：初始节点（<strong>实心圆</strong>）、结束节点（<strong>带圈的实心圆</strong>）、<strong>动作/活动</strong>（圆角矩形）、<strong>分支与监护表达式</strong>（菱形 + <code>[条件]</code>）、<strong>分叉与汇合</strong>（<strong>粗横线</strong>，表示并发）、<strong>泳道</strong>（按责任人划分的纵向区域）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ●                ← 初始节点</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>   ┌────▼────┐</span></span>
<span class="line"><span>   │ 接收订单 │            ← 动作</span></span>
<span class="line"><span>   └────┬────┘</span></span>
<span class="line"><span>   ═════╪═════             ← 分叉（粗横线）：下面两条并发</span></span>
<span class="line"><span>   │         │</span></span>
<span class="line"><span>┌──▼──┐  ┌──▼──┐</span></span>
<span class="line"><span>│填订单│  │开发票│          两条同时进行</span></span>
<span class="line"><span>└──┬──┘  └──┬──┘</span></span>
<span class="line"><span>   ═════╪═════             ← 汇合（粗横线）：都做完才往下</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>   ┌────▼────┐</span></span>
<span class="line"><span>   │  ◇ [未完成] │           ← 分支（菱形）+ 监护表达式</span></span>
<span class="line"><span>   └────┬────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>        ◉                ← 结束节点</span></span></code></pre></div><p><strong>与流程图的区别</strong>（选择题常问）：活动图<strong>支持并发</strong>（分叉/汇合），流程图只有顺序和分支；活动图还能用<strong>泳道</strong>表达&quot;谁负责哪一段&quot;。</p><p><strong>反例演示（易错）</strong>：<strong>分叉（fork）和分支（decision）都画两条出路，但含义相反</strong>——<strong>分支</strong>是&quot;<strong>二选一</strong>，只走一条&quot;（菱形，路上标条件）；<strong>分叉</strong>是&quot;<strong>两条都要走，并发执行</strong>&quot;（粗横线）。看符号不看箭头数量：<strong>菱形 = 选一条，粗横线 = 全走并同时走</strong>。</p>`,14)),r("figure",d,[(n(),a("svg",g,[...t[0]||(t[0]=[s('<defs><marker id="act-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8z" fill="var(--ink)"></path></marker></defs><rect x="35" y="30" width="220" height="305" class="lane"></rect><rect x="255" y="30" width="470" height="305" class="lane"></rect><text x="117" y="54" class="h">顾客泳道</text><text x="454" y="54" class="h">系统泳道</text><circle cx="145" cy="84" r="8" fill="var(--ink)"></circle><path d="M145 92V115" class="e" marker-end="url(#act-arrow)"></path><rect x="90" y="116" width="110" height="38" rx="18" class="act"></rect><text x="111" y="140" class="t">提交订单</text><path d="M200 135H328" class="e" marker-end="url(#act-arrow)"></path><rect x="329" y="116" width="110" height="38" rx="18" class="act"></rect><text x="350" y="140" class="t">校验订单</text><path d="M384 154V173" class="e" marker-end="url(#act-arrow)"></path><path d="M384 174l18 18 -18 18 -18 -18z" fill="var(--surface)" stroke="var(--ink)" stroke-width="2"></path><text x="408" y="196" class="s">[通过]</text><text x="313" y="222" class="s">[不通过]</text><path d="M402 192H520V220" class="e" marker-end="url(#act-arrow)"></path><path d="M366 192H350V255" class="e" marker-end="url(#act-arrow)"></path><rect x="295" y="256" width="110" height="38" rx="18" class="act"></rect><text x="309" y="280" class="t">发送拒绝提示</text><path d="M350 294V331" class="e" marker-end="url(#act-arrow)"></path><circle cx="350" cy="343" r="10" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"></circle><circle cx="350" cy="343" r="5" fill="var(--ink)"></circle><path d="M520 220V232" class="e" marker-end="url(#act-arrow)"></path><path d="M480 234H700" stroke="var(--ink)" stroke-width="7"></path><path d="M520 237V255" class="e" marker-end="url(#act-arrow)"></path><path d="M640 237V255" class="e" marker-end="url(#act-arrow)"></path><rect x="465" y="256" width="110" height="38" rx="18" class="act"></rect><text x="483" y="280" class="t">生成发票</text><rect x="585" y="256" width="110" height="38" rx="18" class="act"></rect><text x="603" y="280" class="t">安排配送</text><path d="M520 294V310" class="e" marker-end="url(#act-arrow)"></path><path d="M640 294V310" class="e" marker-end="url(#act-arrow)"></path><path d="M480 313H700" stroke="var(--ink)" stroke-width="7"></path><path d="M590 317V331" class="e" marker-end="url(#act-arrow)"></path><circle cx="590" cy="343" r="10" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"></circle><circle cx="590" cy="343" r="5" fill="var(--ink)"></circle>',37)])])),t[1]||(t[1]=r("figcaption",null,"菱形后的两条路径只能选一条；粗横线后的两条路径都要完成，才能在下一条粗横线汇合。",-1))]),t[5]||(t[5]=s(`<h3 id="_3-5-状态图-五要素-四类事件-组合状态-★★" tabindex="-1">3.5 状态图：五要素 + 四类事件 + 组合状态 ★★ <a class="header-anchor" href="#_3-5-状态图-五要素-四类事件-组合状态-★★" aria-label="Permalink to &quot;3.5 状态图：五要素 + 四类事件 + 组合状态 ★★&quot;">​</a></h3><p>状态图是&quot;<strong>单个对象的生命史</strong>&quot;：它在这辈子经历过哪些状态、因为什么事件而切换。<strong>五要素必须背齐</strong>：</p><table tabindex="0"><thead><tr><th>要素</th><th>是什么</th><th>画法/写法</th></tr></thead><tbody><tr><td><strong>状态</strong></td><td>对象所处的情形</td><td>圆角矩形，写状态名（空闲/占线/已锁定）</td></tr><tr><td><strong>事件</strong></td><td>触发状态迁移的事情</td><td>转换线<strong>上方</strong>写事件名</td></tr><tr><td><strong>监护条件</strong></td><td>事件发生还不够，还要满足的条件</td><td>方括号写在事件后：<code>turnOn[有水]</code></td></tr><tr><td><strong>动作</strong></td><td>迁移时执行的一句话</td><td>斜线后写：<code>turnOn[有水]/烧水</code></td></tr><tr><td><strong>转换（转移）</strong></td><td>状态之间的那条箭头</td><td>箭头从源状态指向目标状态</td></tr></tbody></table><p><strong>一条完整转换的读法</strong>（把上面四样串起来）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  空闲 ──── turnOn[有水]/烧水 ────▶ 加热中</span></span>
<span class="line"><span>  ↑源状态      ↑事件 ↑监护条件 ↑动作        ↑目标状态</span></span></code></pre></div><p><strong>结构规律（选择题原话）</strong>：一个状态图<strong>只能有一个初态</strong>（实心圆），但<strong>可以有一个或多个终态</strong>（带圈实心圆），<strong>也可以没有终态</strong>（比如一个永远循环的系统）。</p><p><strong>四类事件（问&quot;下面属于哪种事件&quot;）</strong>：</p><table tabindex="0"><thead><tr><th>事件类型</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>信号事件</strong></td><td>对象之间<strong>发送/接收信号</strong>实现通信</td><td>鼠标点击、外部中断</td></tr><tr><td><strong>调用事件</strong></td><td>一个对象<strong>请求调用</strong>另一个对象的操作</td><td>方法调用</td></tr><tr><td><strong>变换事件</strong></td><td><strong>when + 布尔表达式</strong>，条件由假变真即触发</td><td><code>when(温度&gt;100)</code></td></tr><tr><td><strong>时间事件</strong></td><td>到达某时刻或经过某段时间，用 <strong>when / after</strong></td><td><code>after(5秒)</code>、<code>when(日期=10月24日)</code></td></tr></tbody></table><p><strong>状态内部的五个组成部分</strong>（了解即可）：状态名、<strong>entry/exit 动作</strong>（进入/退出该状态要做的事）、<strong>内部转移</strong>（<code>event/action</code>，不跳出本状态）、<strong>子状态</strong>、<strong>延迟事件</strong>（<code>defer</code>，事件先记下、等以后处理）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ┌──────────── Flashlight ────────────┐</span></span>
<span class="line"><span>   │ entry/开灯      do/闪烁五次         │   ← 进入即开灯、在状态内持续闪烁</span></span>
<span class="line"><span>   │ exit/关灯       selfTest/defer      │   ← 退出即关灯；selfTest 事件先延迟</span></span>
<span class="line"><span>   └────────────────────────────────────┘</span></span></code></pre></div><p><strong>组合状态</strong>：一个状态内部还装着子状态，分两种，<strong>这是易混点</strong>：</p><ul><li><strong>顺序子状态</strong>：子状态之间<strong>互斥</strong>（同一时刻只能在一个），要<strong>全部完成</strong>整体才算完成（像是&quot;一串流程分几步&quot;）；</li><li><strong>并发子状态</strong>：某时刻<strong>可以同时达到多个</strong>子状态，内部<strong>并发进行</strong>。</li></ul><p><strong>反例演示（易错）</strong>：题干说&quot;进入该状态后，可以同时进行 A、B 两件事&quot;→ <strong>并发子状态</strong>；说&quot;先做 A、做完再做 B，两步都完成状态才结束&quot;→ <strong>顺序子状态</strong>。判别只看一个字：<strong>&quot;同时&quot;还是&quot;先后&quot;</strong>。</p>`,13)),r("figure",l,[(n(),a("svg",p,[...t[2]||(t[2]=[s('<defs><marker id="state-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8z" fill="var(--ink)"></path></marker></defs><text x="250" y="26" class="h">事件 [监护条件] / 动作 写在状态转换箭头上</text><circle cx="54" cy="127" r="8" fill="var(--ink)"></circle><path d="M62 127H114" class="e" marker-end="url(#state-arrow)"></path><rect x="115" y="101" width="100" height="52" rx="14" class="st"></rect><text x="145" y="132" class="t">待支付</text><path d="M215 118H316" class="e" marker-end="url(#state-arrow)"></path><text x="224" y="101" class="s">支付成功[库存足]/扣库存</text><rect x="317" y="101" width="100" height="52" rx="14" class="st"></rect><text x="347" y="132" class="t">待发货</text><path d="M417 127H500" class="e" marker-end="url(#state-arrow)"></path><text x="434" y="114" class="s">发货</text><rect x="501" y="101" width="100" height="52" rx="14" class="st"></rect><text x="531" y="132" class="t">运输中</text><path d="M601 127H678" class="e" marker-end="url(#state-arrow)"></path><text x="620" y="114" class="s">签收</text><circle cx="697" cy="127" r="12" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"></circle><circle cx="697" cy="127" r="6" fill="var(--ink)"></circle><path d="M165 153V205H288" class="e" marker-end="url(#state-arrow)"></path><text x="175" y="198" class="s">支付超时 / 释放库存</text><rect x="289" y="180" width="100" height="52" rx="14" class="st"></rect><text x="319" y="211" class="t">已取消</text><path d="M389 206H450" class="e" marker-end="url(#state-arrow)"></path><circle cx="469" cy="206" r="12" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"></circle><circle cx="469" cy="206" r="6" fill="var(--ink)"></circle><text x="115" y="254" class="s">状态图描述一个订单对象的状态变化；业务流程的并发责任划分应使用活动图。</text>',26)])])),t[3]||(t[3]=r("figcaption",null,"读状态图时先沿箭头读“源状态—触发事件—条件/动作—目标状态”，不要把状态名与业务步骤混为一谈。",-1))]),t[6]||(t[6]=s('<h3 id="_3-6-构件图-一眼认出供接口和需接口-★" tabindex="-1">3.6 构件图：一眼认出供接口和需接口 ★ <a class="header-anchor" href="#_3-6-构件图-一眼认出供接口和需接口-★" aria-label="Permalink to &quot;3.6 构件图：一眼认出供接口和需接口 ★&quot;">​</a></h3><p>构件图（组件图）专注于<strong>静态实现视图</strong>——把系统拆成可替换的软件构件，画清它们之间谁依赖谁。</p><p><strong>构件符号</strong>：矩形 + 左上角画两个小矩形凸起（像插头），框内写 <code>&lt;&lt;component&gt;&gt;</code>。</p><p><strong>接口的画法（高频识别题，必须记住）</strong>：</p><table tabindex="0"><thead><tr><th>接口</th><th>符号</th><th>记忆法</th></tr></thead><tbody><tr><td><strong>供接口</strong>（provided，我对外提供的服务）</td><td><strong>整圆</strong>（画成一个完整的圆圈）</td><td>我<strong>给出去</strong>的是完整的；圆是<strong>满</strong>的</td></tr><tr><td><strong>需接口</strong>（required，我需要别人提供的服务）</td><td><strong>半圆</strong>（缺了一块的半圆弧）</td><td>我<strong>要往里接</strong>的是缺口；半圆是<strong>缺</strong>的</td></tr></tbody></table><p><strong>口诀</strong>：<strong>整圆供、半圆需</strong>（或&quot;<strong>满的给别人、缺的找别人要</strong>&quot;）。</p><p><strong>反例演示（易错）</strong>：依赖箭头从<strong>需接口</strong>指向<strong>供接口</strong>（谁需要谁 → 指向被依赖方），别画反——画反了会变成&quot;提供方依赖使用方&quot;，逻辑颠倒。构件之间的虚线箭头表示<strong>依赖关系</strong>（一个构件的实现离不开另一个）。</p><h3 id="_3-7-部署图-节点是立体长方体" tabindex="-1">3.7 部署图：节点是立体长方体 <a class="header-anchor" href="#_3-7-部署图-节点是立体长方体" aria-label="Permalink to &quot;3.7 部署图：节点是立体长方体&quot;">​</a></h3><p>部署图给的是<strong>体系结构的静态实施视图</strong>——软件构件<strong>跑在哪些物理节点上</strong>。</p><p><strong>要素</strong>：</p><table tabindex="0"><thead><tr><th>要素</th><th>画法</th></tr></thead><tbody><tr><td><strong>节点</strong>（node）</td><td><strong>立体长方体</strong>（3D 立方体），表示硬件设备/运行环境，如应用服务器、数据库服务器、PC、手机</td></tr><tr><td><strong>构件</strong></td><td>节点框内放构件符号（表示这台机器上部署了什么）</td></tr><tr><td><strong>连接</strong></td><td>节点之间的实线，可标协议（<code>TCP/IP</code>）或构造型（<code>&lt;&lt;Database&gt;&gt;</code>、<code>&lt;&lt;Storage&gt;&gt;</code>）</td></tr></tbody></table><p><strong>识别特征</strong>：图上一旦出现<strong>立体长方体（有厚度、有顶面和侧面）</strong>，就是部署图——这是它和构件图最容易区分的地方（构件图是平的、带两个小凸起；部署图是立体的）。</p><h3 id="_3-8-uml-全图小结与应试动作" tabindex="-1">3.8 UML 全图小结与应试动作 <a class="header-anchor" href="#_3-8-uml-全图小结与应试动作" aria-label="Permalink to &quot;3.8 UML 全图小结与应试动作&quot;">​</a></h3><p><strong>&quot;给场景选图&quot;速判表</strong>（案例题和选择题都用得上）：</p><table tabindex="0"><thead><tr><th>题目在说什么</th><th>该用哪张图</th></tr></thead><tbody><tr><td>系统有哪些功能、谁能用</td><td><strong>用例图</strong></td></tr><tr><td>类的属性、操作、类间关系</td><td><strong>类图</strong></td></tr><tr><td>某一时刻的对象快照</td><td><strong>对象图</strong></td></tr><tr><td>按时间顺序的对象交互</td><td><strong>顺序图</strong></td></tr><tr><td>强调对象链接结构与调用层次的交互</td><td><strong>通信图</strong></td></tr><tr><td><strong>单个对象</strong>因事件而状态变迁</td><td><strong>状态图</strong></td></tr><tr><td>业务流程步骤、有并发/责任人划分</td><td><strong>活动图</strong></td></tr><tr><td>软件拆成哪些可替换构件、接口供需</td><td><strong>构件图</strong></td></tr><tr><td>软件跑在哪些硬件节点上</td><td><strong>部署图</strong></td></tr><tr><td>类如何分组打包、包间依赖</td><td><strong>包图</strong></td></tr></tbody></table><p><strong>应试动作</strong>：</p><ol><li><strong>背分类</strong>：结构图 6 种、行为图 7 种（至少记住高频 10 种的归属）；</li><li><strong>认符号</strong>：三角 = 泛化/实现（虚线是接口实现）、菱形 = 整体部分（空心聚合 / 实心组合）、虚线 = 弱关系（依赖最弱）、<strong>整圆供/半圆需</strong>、<strong>立体长方体 = 部署节点</strong>、<strong>下划线 = 对象</strong>；</li><li><strong>判用例关系</strong>：必经 include（主干指出）、可选 extend（分支指回）；</li><li><strong>状态图五要素</strong>与<strong>四类事件</strong>要能默写（简答题和填空都可能要）。</li></ol>',17))])}const y=o(e,[["render",c]]);export{b as __pageData,y as default};
